#!/usr/bin/env node
// Draws the pixel room (scripts/pixel/) into web/src/assets/pixel/: one PNG per
// sprite at one image pixel per art pixel, and a manifest of their sizes and
// frames for the site. Nothing here is generated by a model or sampled from a
// picture; it is all drawn, the same way every time.
//
//   node scripts/build-pixels.mjs [--preview <dir>]
//
// --preview also writes the whole room composed at 1x, for looking at.

import { mkdirSync, writeFileSync } from 'node:fs';
import os from 'node:os';
import path from 'node:path';

import sharp from 'sharp';

import { MASTER, PANELS, PLACES } from '../web/src/pixel/layout.ts';
import { CURSOR_HOTSPOT, drawCursor } from './pixel/cursor.mjs';
import { drawObjects } from './pixel/objects.mjs';
import { Raster } from './pixel/raster.mjs';
import { drawScene } from './pixel/scene.mjs';

const OUT = 'web/src/assets/pixel';
mkdirSync(OUT, { recursive: true });

const manifest = {};

async function emit(name, raster, extra = {}) {
  await raster.save(`${OUT}/${name}.png`);
  manifest[name] = { w: raster.width, h: raster.height, ...extra };
  console.log(`${name}.png ${raster.width}x${raster.height}`);
}

const scene = drawScene();
const objects = drawObjects();
await emit('scene', scene);
for (const [name, raster, extra] of objects) await emit(name, raster, extra);

writeFileSync(`${OUT}/manifest.json`, `${JSON.stringify(manifest, null, 2)}\n`);
console.log(`${Object.keys(manifest).length} sprites`);

// The cursor, at two CSS pixels to the art pixel (40 by 40, the size the
// First Emissary chose), and at whole multiples of that for denser screens,
// so every art pixel stays square at 1x, 1.5x, 2x and 3x (base.css).
const CURSOR_OUT = 'web/src/assets/cursor';
const CURSOR_SCALES = { '': 2, '@1.5x': 3, '@2x': 4, '@3x': 6 };
mkdirSync(CURSOR_OUT, { recursive: true });
const cursorFile = path.join(os.tmpdir(), 'thalmor-cursor.png');
const cursor = drawCursor();
await cursor.save(cursorFile);
for (const [suffix, k] of Object.entries(CURSOR_SCALES)) {
  await sharp(cursorFile)
    .resize({ width: cursor.width * k, kernel: 'nearest' })
    .png({ compressionLevel: 9, palette: true })
    .toFile(`${CURSOR_OUT}/gauntlet${suffix}.png`);
}
console.log(`cursor ${cursor.width}x${cursor.height}, hotspot ${CURSOR_HOTSPOT.x * 2 + 1} ${CURSOR_HOTSPOT.y * 2 + 1} at 1x`);

const at = process.argv.indexOf('--preview');
if (at > 0) {
  const dir = process.argv[at + 1];
  const sprites = Object.fromEntries(objects.map(([name, raster, extra]) => [name, { raster, fw: extra?.fw ?? raster.width }]));
  const room = new Raster(MASTER.width, MASTER.height);
  room.blit(scene, 0, 0);
  const put = (name, place) => {
    const { raster, fw } = sprites[name];
    const frame = new Raster(fw, raster.height);
    for (let y = 0; y < raster.height; y++) for (let x = 0; x < fw; x++) frame.px[y * fw + x] = raster.px[y * raster.width + x];
    room.blit(frame, MASTER.originX + place.x, MASTER.originY + place.y);
  };
  const SPRITE_OF = {
    archL: 'arch',
    archR: 'arch',
    candleL: 'candle',
    candleR: 'candle',
    sconceL: 'sconce',
    sconceR: 'sconce',
    boughL: 'bough-l',
    boughR: 'bough-r',
  };
  for (const [key, place] of Object.entries(PLACES)) put(SPRITE_OF[key] ?? key, place);
  put('note', PANELS.note);
  put('clock', PANELS.clock);
  mkdirSync(dir, { recursive: true });
  await room.save(`${dir}/room.png`);
  console.log(`preview: ${dir}/room.png`);
}
